<script setup>import {ref} from 'vue';import {readStore,writeStore} from '../data/storage.js';import {Droplet,Heart,MapPin,LockKeyhole,Coins,Users} from 'lucide-vue-next';const posts=ref(readStore('posts',[]));const text=ref('');const nick=ref('');const error=ref('');const examples=[{icon:Droplet,title:'Підготовка до донації',text:'Що варто знати перед здачею крові: харчування, сон і загальні рекомендації.'},{icon:Heart,title:'Досвід першої донації',text:'Ділюся враженнями від першого візиту до центру крові.'},{icon:MapPin,title:'Як знайти центр крові',text:'Поради, як знайти найближчий центр крові у своєму місті.'}];function submit(){if(text.value.trim().length<12){error.value='Додайте щонайменше 12 символів.';return}posts.value.unshift({id:Date.now(),nick:nick.value.trim()||'Учасник',text:text.value.trim()});writeStore('posts',posts.value);text.value='';nick.value='';error.value='';}</script><template><div class="page-intro"><h1>Спільнота</h1><p>Обмін досвідом, підтримка та корисні поради для донорів і пацієнтів.</p></div><div class="community-layout"><section class="surface composer"><h2>Створити допис</h2><label class="field-label">Ім’я (необов’язково)<input v-model="nick" maxlength="40" placeholder="Як до вас звертатися"/></label><label class="field-label">Текст допису<textarea v-model="text" rows="3" maxlength="1000" placeholder="Напишіть про свій досвід, запитайте або поділіться порадою"/></label><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="btn-primary" @click="submit">Опублікувати</button></section><aside class="surface policy-panel"><h2>Правила спільноти</h2><div class="rule"><LockKeyhole/><span>Не публікуйте медичні документи та приватні дані.</span></div><div class="rule"><Coins/><span>Не розміщуйте неперевірені прохання про гроші.</span></div><div class="rule"><Users/><span>Поважайте інших учасників спільноти.</span></div></aside></div><div class="community-posts"><article v-for="post in posts" :key="post.id" class="surface user-post"><strong>{{post.nick}}</strong><p>{{post.text}}</p></article><article v-for="example in examples" :key="example.title" class="surface example-post"><span class="learn-icon"><component :is="example.icon"/></span><div><h3>{{example.title}}</h3><p>{{example.text}}</p></div><span class="example-chevron">›</span></article></div></template>